 EditorSceneManager.OpenScene("Assets/Scenes/DansBackyardReverse.unity");Physics.SyncTransforms();var text=GameObject.Find("LOGGING RIDGE").transform;var board=GameObject.Find("Logging Ridge sign board").transform;var post=GameObject.Find("Logging Ridge grounded sign post").transform;var delta=-text.forward*4;var foot=post.position-Vector3.up*1.2f+delta;float y=Physics.RaycastAll(foot+Vector3.up*5,Vector3.down,10,1,QueryTriggerInteraction.Ignore).Where(h=>h.collider.name.StartsWith("Ground_")).OrderBy(h=>Mathf.Abs(h.point.y-foot.y)).First().point.y;delta.y=y-(post.position.y-1.2f);foreach(var t in new[]{text,board,post})t.position+=delta;EditorSceneManager.MarkSceneDirty(text.gameObject.scene);EditorSceneManager.SaveScene(text.gameObject.scene);
 EditorSceneManager.OpenScene("Assets/Scenes/ForestLoopReverse.unity");Physics.SyncTransforms();var root=GameObject.Find("Forest Reverse natural cave atmosphere").transform;var shell=GameObject.Find("Echo Cave enclosed rock").GetComponent<Collider>();var b=Object.FindObjectsByType<WoodlandRoute>().Single(b=>b.title=="Fern Gully");var rock=AssetDatabase.LoadAssetAtPath<Material>("Assets/Track/UndergroundPolish/Fallen cave stone.mat");var wood=AssetDatabase.LoadAssetAtPath<Material>("Assets/Track/UndergroundPolish/Cave exposed roots.mat");var irregular=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Vegetation/Phase6/IrregularCrown.asset");
