 at=p+side*edge*3.7f;if(shell.Raycast(new Ray(at+Vector3.up*2,Vector3.up),out var roof,30)){Part("Cave tapered ceiling stone",roof.point-Vector3.up*.35f,new(.5f,1.2f,.55f),Quaternion.Euler(180,s*13,0),rock,true);Part("Cave dangling root",roof.point-Vector3.up*.7f,new(.08f,1.55f,.08f),Quaternion.Euler(13,s*7,12),wood,false);Part("Cave branching root",roof.point-Vector3.up*.25f+side*.3f,new(.08f,.7f,.08f),Quaternion.Euler(0,0,55),wood,false);added+=3;}
 }}EditorSceneManager.MarkSceneDirty(root.gameObject.scene);EditorSceneManager.SaveScene(root.gameObject.scene);AssetDatabase.SaveAssets();File.AppendAllText("Docs/UndergroundPolish/cave-span.txt",$"\nAdded {added} cave-local shoulder/ceiling rocks and roots, all non-colliding and outside central corridor.");EditorSceneManager.OpenScene("Assets/Scenes/DansBackyardReverse.unity");AssetDatabase.Refresh();return "Sign clear of checkpoint upright; mottled surfaces and cave-local natural details";
